"""Pick the best hand(s) from a list of poker hands."""

from collections import Counter

RANKS = "23456789TJQKA"
RANK_VALUES = {rank: value for value, rank in enumerate(RANKS, start=2)}


def _card_value(card):
    return RANK_VALUES[card[0]]


def _hand_score(hand):
    """Return a tuple that ranks a hand; higher tuples win."""
    cards = hand.split()
    values = sorted((_card_value(card) for card in cards), reverse=True)
    suits = {card[1] for card in cards}
    counts = Counter(values)
    # Group ranks by count, e.g. {4: 5, 1: 3} for four of a kind.
    by_count = sorted(counts.items(), key=lambda item: (-item[1], -item[0]))

    if len(suits) == 1 and _is_straight(values):
        # Straight flush: category 8, then the straight's high card.
        return (8, _straight_high(values))

    if by_count[0][1] == 4:
        quad, kicker = by_count[0][0], by_count[1][0]
        return (7, quad, kicker)

    if by_count[0][1] == 3:
        if by_count[1][1] == 2:
            # Full house: category 6, then the triplet, then the pair.
            return (6, by_count[0][0], by_count[1][0])
        return (5, by_count[0][0], *by_count[1:])

    if len(suits) == 1:
        return (4, *values)

    if _is_straight(values):
        return (3, _straight_high(values))

    if by_count[0][1] == 3:
        return (5, by_count[0][0], *by_count[1:])

    if by_count[0][1] == 2:
        if by_count[1][1] == 2:
            # Two pair: category 2, then the pairs (high to low), then kicker.
            return (2, by_count[0][0], by_count[1][0], by_count[2][0])
        return (1, by_count[0][0], *by_count[1:])

    return (0, *values)


def _is_straight(values):
    if values == [14, 5, 4, 3, 2]:
        return True
    return values[0] - values[-1] == 4 and len(set(values)) == 5


def _straight_high(values):
    # The wheel (A-2-3-4-5) scores as a 5-high straight.
    if values == [14, 5, 4, 3, 2]:
        return 5
    return values[0]


def best_hands(hands):
    scores = [(hand, _hand_score(hand)) for hand in hands]
    best = max(score for _, score in scores)
    return [hand for hand, score in scores if score == best]

